#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
#include <set>
#include <stack>
#include <algorithm>

#define FOR(A, B) for (A = 0; A < B; A++)

using namespace std;

vector<long long> luckies;
int l, lim1, lim2;

void gen(long long c)
{
    if (c > lim2) return;
    if (l > 0 && c >= lim1) luckies.push_back(c);

    l++;
    gen(c * 10 + 4);
    gen(c * 10 + 7);
    l--;
}

int main()
{
    int i, j, k, m, pl, pr, vl, vr;
    scanf("%d %d %d %d %d", &vl, &vr, &pl, &pr, &k);

    l = 0;
    lim1 = min(vl, pl);
    lim2 = max(vr, pr);
    gen(0);

    int q = 0;
    for (i = vl; i <= vr; i++) {
        for (j = pl; j <= pr; j++) {
            int p = 0;
            for (m = 0; m < static_cast<int>(luckies.size()); m++) {
                if (luckies[m] >= min(i, j) &&
                    luckies[m] <= max(i, j)) {
                    p++;
                }
            }
            if (p == k) {
                q++;
            }
        }
    }

    double total = static_cast<double>(vr - vl + 1) * (pr - pl + 1);
    printf("%lf", static_cast<double>(q) / total);

    return 0;
}

